<script setup>
import { computed } from 'vue'
import { RouterLink } from 'vue-router'
import { useCartStore } from '../../stores/cart'
import { storeSettings } from '../../data/mockData'
import { formatCurrency } from '../../utils/formatCurrency'

const cart = useCartStore()
const remaining = computed(() => Math.max(storeSettings.freeShippingThreshold - cart.subtotal, 0))
const progress = computed(() => Math.min((cart.subtotal / storeSettings.freeShippingThreshold) * 100, 100))
</script>

<template>
  <Teleport to="body"><div v-if="cart.drawerOpen" class="fixed inset-0 z-100"><button class="absolute inset-0 bg-black/45" aria-label="Cerrar carrito" @click="cart.closeDrawer"></button><aside class="absolute bottom-0 right-0 top-0 flex w-full max-w-md flex-col bg-white shadow-2xl"><header class="flex items-center justify-between border-b border-pink-100 px-6 py-5"><h2 class="text-xl font-bold">Tu carrito</h2><button class="rounded-full p-2 text-xl hover:bg-pink-50" aria-label="Cerrar" @click="cart.closeDrawer">×</button></header><div v-if="cart.items.length" class="flex-1 overflow-y-auto px-6 py-5"><div class="rounded-xl bg-pink-50 p-4 text-center text-sm text-neutral-600"><p v-if="remaining">Te faltan <strong class="text-[var(--primary)]">{{ formatCurrency(remaining) }}</strong> para envío gratis.</p><p v-else class="font-bold text-[var(--primary)]">¡Desbloqueaste el envío gratis!</p><div class="mt-3 h-1.5 overflow-hidden rounded-full bg-pink-100"><div class="h-full rounded-full bg-[var(--primary)]" :style="{ width: `${progress}%` }"></div></div></div><article v-for="item in cart.items" :key="item.id" class="flex gap-4 border-b border-pink-100 py-5"><img :src="item.image" :alt="item.name" class="size-22 rounded-xl bg-pink-50 object-contain p-1" /><div class="min-w-0 flex-1"><div class="flex justify-between gap-3"><div><p class="text-xs font-bold text-[var(--primary)]">{{ item.category }}</p><h3 class="mt-1 truncate font-bold">{{ item.name }}</h3></div><button class="text-lg text-neutral-500 hover:text-red-500" aria-label="Eliminar producto" @click="cart.remove(item.id)">×</button></div><p class="mt-2 font-semibold">{{ formatCurrency(item.price) }}</p><div class="mt-3 inline-flex items-center rounded-full border border-pink-200"><button class="size-8 text-[var(--primary)]" @click="cart.updateQuantity(item.id, item.quantity - 1)">−</button><span class="w-7 text-center text-sm font-bold">{{ item.quantity }}</span><button class="size-8 text-[var(--primary)]" :disabled="item.quantity === item.stock" @click="cart.updateQuantity(item.id, item.quantity + 1)">+</button></div></div></article></div><div v-else class="flex flex-1 flex-col items-center justify-center p-8 text-center"><span class="text-5xl">🛍</span><h3 class="mt-5 text-xl font-bold">Tu carrito está vacío</h3><p class="mt-2 text-sm text-neutral-500">Agrega tus productos favoritos para continuar.</p><RouterLink class="mt-6 rounded-full bg-[var(--primary)] px-5 py-3 text-sm font-bold text-white" to="/tienda" @click="cart.closeDrawer">Ir a la tienda</RouterLink></div><footer v-if="cart.items.length" class="border-t border-pink-100 px-6 py-5"><div class="flex justify-between text-lg"><span>Subtotal</span><strong>{{ formatCurrency(cart.subtotal) }}</strong></div><RouterLink class="mt-4 block rounded-full bg-[var(--primary)] py-3 text-center text-sm font-bold text-white transition hover:bg-[var(--info)]" to="/carrito" @click="cart.closeDrawer">Finalizar compra</RouterLink><button class="mt-3 w-full text-sm font-bold text-neutral-600 hover:text-[var(--primary)]" @click="cart.closeDrawer">Seguir comprando</button></footer></aside></div></Teleport>
</template>
